  _o.CONDUCTIVITY_COEFFICIENT_C = this.CONDUCTIVITY_COEFFICIENT_C();
  _o.CONDUCTIVITY_EXPONENT_D = this.CONDUCTIVITY_EXPONENT_D();
  _o.REFERENCE_FREQUENCY_MHZ = this.REFERENCE_FREQUENCY_MHZ();
  _o.RELATIVE_PERMITTIVITY_REAL = this.RELATIVE_PERMITTIVITY_REAL();
  _o.RELATIVE_PERMITTIVITY_IMAGINARY = this.RELATIVE_PERMITTIVITY_IMAGINARY();
