  _o.TRANSMISSION_LOSS_DB = this.TRANSMISSION_LOSS_DB();
  _o.ATTENUATION_DB_PER_M = this.ATTENUATION_DB_PER_M();
  _o.ABSORPTION_COEFFICIENT = this.ABSORPTION_COEFFICIENT();
  _o.SURFACE_ROUGHNESS_RMS_M = this.SURFACE_ROUGHNESS_RMS_M();
  _o.ROUGHNESS_CORRELATION_LENGTH_M = this.ROUGHNESS_CORRELATION_LENGTH_M();
