export class RFST implements flatbuffers.IGeneratedObject {
constructor(
  public MATERIAL_ID: string|Uint8Array|null = null,
  public NAME: string|Uint8Array|null = null,
  public MATERIAL_CLASS: rfsMaterialClass = rfsMaterialClass.UNSPECIFIED,
  public DESCRIPTION: string|Uint8Array|null = null,
  public FREQUENCY_MIN_MHZ: number = 0.0,
  public FREQUENCY_MAX_MHZ: number = 0.0,
  public PERMITTIVITY_COEFFICIENT_A: number = 0.0,
  public PERMITTIVITY_EXPONENT_B: number = 0.0,
  public CONDUCTIVITY_COEFFICIENT_C: number = 0.0,
  public CONDUCTIVITY_EXPONENT_D: number = 0.0,
  public REFERENCE_FREQUENCY_MHZ: number = 0.0,
  public RELATIVE_PERMITTIVITY_REAL: number = 0.0,
  public RELATIVE_PERMITTIVITY_IMAGINARY: number = 0.0,
  public CONDUCTIVITY_S_PER_M: number = 0.0,
  public LOSS_TANGENT: number = 0.0,
  public RELATIVE_PERMEABILITY_REAL: number = 0.0,
  public RELATIVE_PERMEABILITY_IMAGINARY: number = 0.0,
  public REFLECTIVITY: number = 0.0,
  public REFLECTION_LOSS_DB: number = 0.0,
  public THICKNESS_M: number = 0.0,
  public TRANSMISSION_LOSS_DB: number = 0.0,
  public ATTENUATION_DB_PER_M: number = 0.0,
  public ABSORPTION_COEFFICIENT: number = 0.0,
  public SURFACE_ROUGHNESS_RMS_M: number = 0.0,
  public ROUGHNESS_CORRELATION_LENGTH_M: number = 0.0,
  public SCATTERING_CLASS: rfsScatteringClass = rfsScatteringClass.UNSPECIFIED,
  public DIFFUSE_SCATTERING_COEFFICIENT: number = 0.0,
  public BACKSCATTER_COEFFICIENT_DB: number = 0.0,
  public TEMPERATURE_K: number = 0.0,
  public MOISTURE_CONTENT_FRACTION: number = 0.0,
  public SALINITY_PSU: number = 0.0,
  public FREQUENCY_SAMPLES: (RFSFrequencySampleT)[] = [],
  public REFLECTION_TABLE: (RFSReflectionEntryT)[] = [],
  public GEOMETRY: (RFSGeometryRefT)[] = [],
  public PROVENANCE: RFSProvenanceT|null = null,
  public COMPUTED_AT: bigint = BigInt('0'),
  public PRODUCER_ID: string|Uint8Array|null = null,
  public SIGNATURE: (number)[] = []
){}


pack(builder:flatbuffers.Builder): flatbuffers.Offset {
  const MATERIAL_ID = (this.MATERIAL_ID !== null ? builder.createString(this.MATERIAL_ID!) : 0);
  const NAME = (this.NAME !== null ? builder.createString(this.NAME!) : 0);
  const DESCRIPTION = (this.DESCRIPTION !== null ? builder.createString(this.DESCRIPTION!) : 0);
  const FREQUENCY_SAMPLES = RFS.createFrequencySamplesVector(builder, builder.createObjectOffsetList(this.FREQUENCY_SAMPLES));
  const REFLECTION_TABLE = RFS.createReflectionTableVector(builder, builder.createObjectOffsetList(this.REFLECTION_TABLE));
  const GEOMETRY = RFS.createGeometryVector(builder, builder.createObjectOffsetList(this.GEOMETRY));
  const PROVENANCE = (this.PROVENANCE !== null ? this.PROVENANCE!.pack(builder) : 0);
  const PRODUCER_ID = (this.PRODUCER_ID !== null ? builder.createString(this.PRODUCER_ID!) : 0);
  const SIGNATURE = RFS.createSignatureVector(builder, this.SIGNATURE);

  RFS.startRFS(builder);
  RFS.addMaterialId(builder, MATERIAL_ID);
  RFS.addName(builder, NAME);
  RFS.addMaterialClass(builder, this.MATERIAL_CLASS);
  RFS.addDescription(builder, DESCRIPTION);
  RFS.addFrequencyMinMhz(builder, this.FREQUENCY_MIN_MHZ);
  RFS.addFrequencyMaxMhz(builder, this.FREQUENCY_MAX_MHZ);
  RFS.addPermittivityCoefficientA(builder, this.PERMITTIVITY_COEFFICIENT_A);
  RFS.addPermittivityExponentB(builder, this.PERMITTIVITY_EXPONENT_B);
  RFS.addConductivityCoefficientC(builder, this.CONDUCTIVITY_COEFFICIENT_C);
  RFS.addConductivityExponentD(builder, this.CONDUCTIVITY_EXPONENT_D);
  RFS.addReferenceFrequencyMhz(builder, this.REFERENCE_FREQUENCY_MHZ);
  RFS.addRelativePermittivityReal(builder, this.RELATIVE_PERMITTIVITY_REAL);
  RFS.addRelativePermittivityImaginary(builder, this.RELATIVE_PERMITTIVITY_IMAGINARY);
  RFS.addConductivitySPerM(builder, this.CONDUCTIVITY_S_PER_M);
  RFS.addLossTangent(builder, this.LOSS_TANGENT);
  RFS.addRelativePermeabilityReal(builder, this.RELATIVE_PERMEABILITY_REAL);
  RFS.addRelativePermeabilityImaginary(builder, this.RELATIVE_PERMEABILITY_IMAGINARY);
  RFS.addReflectivity(builder, this.REFLECTIVITY);
  RFS.addReflectionLossDb(builder, this.REFLECTION_LOSS_DB);
  RFS.addThicknessM(builder, this.THICKNESS_M);
  RFS.addTransmissionLossDb(builder, this.TRANSMISSION_LOSS_DB);
  RFS.addAttenuationDbPerM(builder, this.ATTENUATION_DB_PER_M);
  RFS.addAbsorptionCoefficient(builder, this.ABSORPTION_COEFFICIENT);
  RFS.addSurfaceRoughnessRmsM(builder, this.SURFACE_ROUGHNESS_RMS_M);
  RFS.addRoughnessCorrelationLengthM(builder, this.ROUGHNESS_CORRELATION_LENGTH_M);
  RFS.addScatteringClass(builder, this.SCATTERING_CLASS);
  RFS.addDiffuseScatteringCoefficient(builder, this.DIFFUSE_SCATTERING_COEFFICIENT);
  RFS.addBackscatterCoefficientDb(builder, this.BACKSCATTER_COEFFICIENT_DB);
  RFS.addTemperatureK(builder, this.TEMPERATURE_K);
  RFS.addMoistureContentFraction(builder, this.MOISTURE_CONTENT_FRACTION);
  RFS.addSalinityPsu(builder, this.SALINITY_PSU);
  RFS.addFrequencySamples(builder, FREQUENCY_SAMPLES);
  RFS.addReflectionTable(builder, REFLECTION_TABLE);
  RFS.addGeometry(builder, GEOMETRY);
  RFS.addProvenance(builder, PROVENANCE);
  RFS.addComputedAt(builder, this.COMPUTED_AT);
  RFS.addProducerId(builder, PRODUCER_ID);
  RFS.addSignature(builder, SIGNATURE);

  return RFS.endRFS(builder);
}
}
